import { useEffect, useState } from "react";
import { io } from "socket.io-client";

const socket = io("http://localhost:5000");

function AdminDashboard() {

  const [queues, setQueues] = useState([]);

  const fetchQueues = async () => {
    const res = await fetch("http://localhost:5000/api/queue/all");
    const data = await res.json();
    setQueues(data);
  };

  useEffect(() => {
    fetchQueues();

    socket.on("queueUpdated", fetchQueues);

    socket.on("notification", (msg) => {
      console.log(msg);
    });

    return () => socket.off();
  }, []);

  const confirm = async (id) => {
    await fetch(`http://localhost:5000/api/queue/confirm/${id}`, {
      method: "PUT"
    });
  };

  const complete = async (id) => {
    await fetch(`http://localhost:5000/api/queue/complete/${id}`, {
      method: "DELETE"
    });
  };

  return (
    <div style={{ padding: 20 }}>

      <h2>👨‍⚕️ Admin Panel</h2>

      {queues.map((q) => (
        <div key={q._id}>
          <p>{q.patientName}</p>
          <p>{q.status}</p>

          {q.status === "Waiting" && (
            <button onClick={() => confirm(q._id)}>Confirm</button>
          )}

          <button onClick={() => complete(q._id)}>Complete</button>
        </div>
      ))}

    </div>
  );
}

export default AdminDashboard;
